//! Differential test: `round(x, ndigits)` gives CPython's answer.
//!
//! Expression Language §2.2.2 rounds half-to-even on the exact value of the
//! input, as Python's `round` does, and an `int` result outside the 64-bit
//! signed range is an integer overflow error. The expected results come from
//! `data/round_cpython.txt`, generated by
//! `scripts/generate_round_cpython_fixture.py` with CPython 3.12 and checked
//! in, so these tests do not run Python. An `int` result is the exact
//! rounded value (`round(Fraction(x), n)` for a float `x`), which is the
//! value CPython's float result approximates; the script checks that they
//! agree wherever the float is exact.

use openjd_expr::{ExprValue, ExpressionErrorKind, ParsedExpression, SymbolTable};

const FIXTURE: &str = include_str!("data/round_cpython.txt");

fn eval(expr: &str) -> Result<ExprValue, openjd_expr::ExpressionError> {
    ParsedExpression::new(expr).and_then(|p| p.evaluate(&SymbolTable::new()))
}

/// Compare one fixture line with openjd. Returns a description of the
/// difference, or `None` when openjd agrees with CPython.
fn check(line: &str) -> Option<String> {
    let f: Vec<&str> = line.split(' ').collect();
    let (x, n, expected) = match f[0] {
        "f" => {
            let bits = u64::from_str_radix(f[1], 16).expect("fixture bits");
            // The literal must read back as the double CPython rounded.
            match eval(f[2]) {
                Ok(ExprValue::Float(v)) if v.value().to_bits() == bits => {}
                // openjd has no signed zero, so -0.0 reads back as 0.0.
                Ok(ExprValue::Float(v)) if v.value() == 0.0 && f64::from_bits(bits) == 0.0 => {}
                other => return Some(format!("{line}: literal reads as {other:?}")),
            }
            (f[2], f[3], &f[4..])
        }
        "i" => (f[1], f[2], &f[3..]),
        _ => panic!("malformed fixture line: {line:?}"),
    };
    let expr = format!("round({x}, {n})");
    let got = eval(&expr);
    let ok = match (expected, &got) {
        (["int", r], Ok(ExprValue::Int(v))) => r.parse::<i64>().expect("fixture int") == *v,
        (["overflow"], Err(e)) => matches!(e.kind(), ExpressionErrorKind::IntegerOverflow),
        (["float", rbits, text], Ok(ExprValue::Float(v))) => {
            let rbits = u64::from_str_radix(rbits, 16).expect("fixture bits");
            // The fixture writes a zero result unsigned; openjd normalizes
            // -0.0 to 0.0, so compare zeros by value.
            let r = f64::from_bits(rbits);
            let same = v.value().to_bits() == rbits || (r == 0.0 && v.value() == 0.0);
            same && ExprValue::Float(v.clone()).to_display_string() == *text
        }
        _ => false,
    };
    (!ok).then(|| format!("{expr}: expected {expected:?}, got {got:?}"))
}

#[test]
fn round_matches_cpython() {
    let lines: Vec<&str> = FIXTURE
        .lines()
        .filter(|line| !line.starts_with('#') && !line.is_empty())
        .collect();
    // Guard against a truncated fixture silently testing less.
    assert!(lines.len() > 1500, "fixture has {} cases", lines.len());
    let failures: Vec<String> = lines.iter().filter_map(|l| check(l)).collect();
    assert!(
        failures.is_empty(),
        "{} of {} cases differ from CPython:\n{}",
        failures.len(),
        lines.len(),
        failures
            .iter()
            .take(40)
            .cloned()
            .collect::<Vec<_>>()
            .join("\n")
    );
}
